// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());

        address oldOwner = c.owner();
        vm.prank(caller);
        bool success = c.setOwner(newOwner);

        assertTrue(c.owner() == oldOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;

    function setUp() public {
        c = new C();
        originalOwner = c.owner();
    }

    function testFuzz_property(address nonOwner, address newOwner) public {
        // Restrict nonOwner to be different from the original owner so the call is unauthorized
        vm.assume(nonOwner != originalOwner);
        // Ensure newOwner is not the zero address, but not strictly required
        vm.assume(newOwner != address(0));

        address currentOwnerBefore = c.owner();
        vm.prank(nonOwner);
        c.setOwner(newOwner);

        // After an unauthorized call, the correct contract keeps owner unchanged,
        // while the buggy contract sets owner to newOwner.
        assertTrue(c.owner() == currentOwnerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(msg.sender == c.owner());
        vm.prank(c.owner());
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        assertTrue(ok && abi.decode(ret, (bool)));
    }
}
